const ruinHoundSheet=new Image();ruinHoundSheet.assetSrc='assets/ruin-hound-v2.png';
function beginRuinHound(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy),ux=len?dx/len:1,uy=len?dy/len:0;e.state='attack';e.elapsed=0;e.struck=false;e.facing=ux-uy<0?-1:1;e.attack={pattern:'ruinTripwire',bespoke:true,windup:3.05,origin:{x:e.x,y:e.y},last:{x:e.x,y:e.y},center:{x:e.x+ux*Math.max(60,len-40),y:e.y+uy*Math.max(60,len-40)},ux,uy,previous:{x:p.x,y:p.y},target:null,chargeAt:null,blocked:false,hit:false};}
function ruinHoundCross(a,from,to){let signed=q=>(q.x-a.center.x)*a.ux+(q.y-a.center.y)*a.uy,s=signed(from),t=signed(to);if(Math.abs(s-t)<1e-8||s*t>0||Math.abs(s)<1e-8)return null;let k=s/(s-t);if(k<0||k>1)return null;let point={x:from.x+(to.x-from.x)*k,y:from.y+(to.y-from.y)*k},side=-(point.x-a.center.x)*a.uy+(point.y-a.center.y)*a.ux;return Math.abs(side)<=150+1e-8?point:null;}
function ruinHoundContact(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d2=dx*dx+dy*dy;if(d2<1e-10)return false;let t=Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d2));return Math.hypot(point.x-start.x-dx*t,point.y-start.y-dy*t)<=30+1e-8;}
function lockRuinHound(e,target,at){let a=e.attack,dx=target.x-a.origin.x,dy=target.y-a.origin.y,len=Math.hypot(dx,dy),reach=Math.min(320,len),end={...a.origin};for(let n=6;n<reach+6;n+=6){let d=Math.min(n,reach),q={x:a.origin.x+dx/(len||1)*d,y:a.origin.y+dy/(len||1)*d};if(!passable(q.x,q.y,22)||!lineClear(end,q,22)){a.blocked=true;break;}end=q;}a.target=end;a.chargeAt=Math.round((at+.65)*1e6)/1e6;a.windup=a.chargeAt;playSound('impact',e.x,e.y);}
const ruinHoundAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e0')return ruinHoundAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='ruinTripwire'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=360&&clear){beginRuinHound(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,108*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.target){let crossed=before>=.65?ruinHoundCross(a,a.previous,p):null;if(crossed)lockRuinHound(e,crossed,e.elapsed);else if(e.elapsed>=2.4)lockRuinHound(e,{x:p.x,y:p.y},2.4);a.previous={x:p.x,y:p.y};}
 if(a.target&&e.elapsed>=a.chargeAt){let ratio=Math.min(1,(e.elapsed-a.chargeAt)/.35),q={x:a.origin.x+(a.target.x-a.origin.x)*ratio,y:a.origin.y+(a.target.y-a.origin.y)*ratio},from={x:e.x,y:e.y},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6));if(!a.crashed)for(let j=0;j<n;j++){let next={x:e.x+dx/n,y:e.y+dy/n};if(!passable(next.x,next.y,22)||!lineClear(e,next,22)){a.crashed=true;break;}e.x=next.x;e.y=next.y;}a.last={x:e.x,y:e.y};if(Math.hypot(dx,dy)>.01)e.facing=dx-dy<0?-1:1;if(!a.hit&&ruinHoundContact(p,from,a.last)&&lineClear(e,p)){a.hit=true;e.struck=true;hurt(84);playSound('impact',e.x,e.y);}}
 if(a.target&&e.elapsed>=a.chargeAt+1.35){e.attack=null;e.state='idle';e.t=2.5;}
};
const ruinHoundDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e0'||!ruinHoundSheet.complete||!ruinHoundSheet.naturalWidth||!ruinHoundSheet.naturalHeight)return ruinHoundDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='ruinTripwire')f={row:2,col:!e.attack.target?0:e.elapsed<e.attack.chargeAt?1:e.elapsed<e.attack.chargeAt+.35?2:3};let q=project(e.x,e.y),sw=ruinHoundSheet.naturalWidth/4,sh=ruinHoundSheet.naturalHeight/3,w=255,h=w*sh/sw,anchor=[.82,.77,.75][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,ruinHoundSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(ruinHoundSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const ruinHoundSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e0'?160:ruinHoundSizeBase(e);
const ruinHoundGroundBase=drawGroundEffects;drawGroundEffects=()=>{ruinHoundGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e0'):enemies)){let a=e.attack;if(e.species!=='r9e0'||e.hp<=0||a?.pattern!=='ruinTripwire'||!visibleAt(e.x,e.y))continue;if(!a.target){let from=project(a.center.x-a.uy*150,a.center.y+a.ux*150),to=project(a.center.x+a.uy*150,a.center.y-a.ux*150);ctx.save();ctx.strokeStyle=e.elapsed<.65?'#7e9ea477':'#a8e8ed';ctx.lineWidth=e.elapsed<.65?1:3;ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.restore();for(let k of [-150,0,150])groundRing(a.center.x-a.uy*k,a.center.y+a.ux*k,12,'#a8e8ed',1);}else if(e.elapsed<a.chargeAt+.35){let dx=a.target.x-a.origin.x,dy=a.target.y-a.origin.y,len=Math.hypot(dx,dy),nx=-dy/(len||1)*30,ny=dx/(len||1)*30;ctx.save();ctx.fillStyle='#d9b77933';ctx.strokeStyle='#f3d196';ctx.lineWidth=2;ctx.beginPath();for(let [i,q]of [{x:a.origin.x+nx,y:a.origin.y+ny},{x:a.target.x+nx,y:a.target.y+ny},{x:a.target.x-nx,y:a.target.y-ny},{x:a.origin.x-nx,y:a.origin.y-ny}].entries()){let v=project(q.x,q.y);if(i)ctx.lineTo(v.x,v.y);else ctx.moveTo(v.x,v.y);}ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();groundRing(a.target.x,a.target.y,30,'#f3d196',2);}else groundRing(e.x,e.y,32,'#a5d8c5',1);}};

